<?php
require dirname(__DIR__,2).'/app/admin_view.php';admin_header('services','Service controller');
$slug=preg_replace('/[^a-z0-9-]/','',(string)($_GET['slug']??''));?>
<div class="toolbar"><a class="btn" href="/admin/">← Admin overview</a><span class="muted">Every customer service page has its own controller and analytics view.</span></div>
<div id="service-content"><p class="muted">Loading service analytics…</p></div>
<script>
const slug=<?=json_encode($slug)?>,root=document.getElementById('service-content'),notice=document.getElementById('notice');let data=null;
function serviceIcon(key){const paths={social:'<path d="m3 11 18-5-5 18-4-8-9-5Z"/><path d="m12 16 5-5"/>',music:'<path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/>',verify:'<path d="M12 3 4 6v5c0 5 3.5 8.4 8 10 4.5-1.6 8-5 8-10V6l-8-3Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/>',web:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M8 9v11"/>',account:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',press:'<path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h5"/>',smm:'<path d="M20.8 8.6c0 4.4-8.8 10-8.8 10s-8.8-5.6-8.8-10A4.6 4.6 0 0 1 12 6.3a4.6 4.6 0 0 1 8.8 2.3Z"/>',phone:'<rect x="6" y="2.5" width="12" height="19" rx="2"/><path d="M10 18.5h4"/>',bot:'<rect x="4" y="7" width="16" height="13" rx="3"/><path d="M12 3v4M9 13h.01M15 13h.01M9 17h6"/>',proxy:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18Z"/>'};const keyBySlug={'social-ads':'social',music:'music',verification:'verify','web-dev':'web','account-mgmt':'account',press:'press',smm:'smm',numbers:'phone',bots:'bot',proxies:'proxy'};return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[keyBySlug[key]||'web']}</svg>`;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function load(){const r=await fetch('/api/admin-service.php?slug='+encodeURIComponent(slug),{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok){root.textContent=d.error||'Unable to load this service.';return;}data=d;draw();}
function draw(){const p=data.page,s=data.stats,services=data.services;const max=Math.max(1,...data.trend.map(x=>Number(x.orders_count)));const bars=data.trend.map((x,i)=>{const h=Math.max(4,Number(x.orders_count)/max*140);return `<rect x="${i*22+6}" y="${160-h}" width="13" height="${h}" rx="3" fill="#6366f1"><title>${esc(x.day)} · ${x.orders_count} orders · £${Number(x.value_total).toFixed(2)}</title></rect>`;}).join('');
root.innerHTML=`<div class="toolbar"><span class="service-icon">${serviceIcon(slug)}</span><h2 style="margin:0">${esc(p.name)}</h2><span class="badge">${p.active?'Visible on user dashboard':'Hidden from user dashboard'}</span></div><div class="stats"><div class="stat"><span>Total orders</span><strong>${Number(s.total)}</strong></div><div class="stat"><span>Income after refunds</span><strong>£${Number(s.income).toFixed(2)}</strong></div><div class="stat"><span>Requests to review</span><strong>${Number(s.pending)}</strong></div><div class="stat"><span>In progress</span><strong>${Number(s.processing)}</strong></div><div class="stat"><span>Completed / publications</span><strong>${Number(s.completed)}</strong></div><div class="stat"><span>Customers</span><strong>${Number(s.customers)}</strong></div><div class="stat"><span>Average order</span><strong>£${Number(s.average_value).toFixed(2)}</strong></div></div><div class="split"><section class="panel"><h2>Orders and publication activity · last 30 days</h2><svg class="chart" viewBox="0 0 680 180" preserveAspectRatio="none"><line x1="0" y1="160" x2="680" y2="160" stroke="#edf0f5"/>${bars}</svg><p class="muted">Bars show orders received per day. Completed orders are the published or delivered count for this service.</p></section><section class="panel"><h2>Service page controls</h2><div class="form-grid"><div class="field"><label>Dashboard label</label><input class="input" id="page-name" value="${esc(p.name)}"></div><div class="field"><label>Dashboard icon</label><input class="input" id="page-icon" maxlength="80" value="${esc(p.icon)}"></div><div class="field" style="grid-column:1/-1"><label>Dashboard description</label><textarea id="page-description" maxlength="500">${esc(p.description)}</textarea></div><label><input type="checkbox" id="page-active" ${p.active?'checked':''}> Show this service on user dashboard</label><button class="btn primary" onclick="savePage()">Save service page</button></div></section></div><section class="panel"><h2>Requests, orders, and publications</h2>${data.orders.length?`<table><thead><tr><th>Order</th><th>Customer</th><th>Request details</th><th>Amount</th><th>Status</th><th>Update request</th></tr></thead><tbody>${data.orders.map(o=>{let details='';try{details=JSON.stringify(typeof o.details==='string'?JSON.parse(o.details):o.details||{});}catch{}return `<tr><td>#${o.id}<br><small class="muted">${esc(o.created_at)}</small></td><td>${esc(o.customer)}<br><small class="muted">${esc(o.email)}</small></td><td><strong>${esc(o.service)}</strong><br>${esc(o.description)}<br><small class="muted">${esc(details)}</small></td><td>£${Number(o.amount).toFixed(2)}</td><td><span class="badge">${esc(o.status)}</span></td><td><select class="input" id="status-${o.id}">${['pending','processing','completed','rejected','cancelled'].map(st=>`<option value="${st}" ${st===o.status?'selected':''}>${st}</option>`).join('')}</select><textarea class="input" id="note-${o.id}" maxlength="4000" placeholder="Customer-visible update">${esc(o.admin_note||'')}</textarea><button class="btn small" onclick="saveOrder(${o.id})">Save update</button></td></tr>`;}).join('')}</tbody></table>`:'<p class="empty">No requests or publications have been submitted for this service.</p>'}</section><section class="panel"><h2>Related catalog prices</h2>${services.length?`<table><thead><tr><th>Catalog item</th><th>Price GBP</th><th>Active</th><th>Save</th></tr></thead><tbody>${services.map(x=>`<tr><td>${esc(x.name)}<br><small class="muted">${esc(x.slug)} · ${esc(x.pricing_mode)}</small></td><td><input class="input short" id="price-${x.id}" type="number" min="0" step="0.01" value="${Number(x.price).toFixed(2)}"></td><td><input type="checkbox" id="active-${x.id}" ${x.active?'checked':''}></td><td><button class="btn small" onclick="savePrice(${x.id})">Save price</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">This service page has no catalog items mapped to it yet.</p>'}</section>`;}
async function send(action,values){const r=await fetch('/api/admin-service.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':data.csrf},body:JSON.stringify({action,slug,...values})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to save changes.');notice.textContent='Saved.';notice.className='notice';await load();}
function savePage(){send('page_update',{name:document.getElementById('page-name').value,icon:document.getElementById('page-icon').value,description:document.getElementById('page-description').value,active:document.getElementById('page-active').checked}).catch(e=>{notice.textContent=e.message;notice.className='notice error';});}
function saveOrder(id){send('order_update',{id,status:document.getElementById('status-'+id).value,note:document.getElementById('note-'+id).value}).catch(e=>{notice.textContent=e.message;notice.className='notice error';});}
function savePrice(id){send('service_update',{id,price:document.getElementById('price-'+id).value,active:document.getElementById('active-'+id).checked}).catch(e=>{notice.textContent=e.message;notice.className='notice error';});}
load();
</script>
<?php admin_footer(); ?>
